SELECT ?uri ?id ?class WHERE {
  ?uri ref:hasExternalReference ?id .
  FILTER(str(?uri) LIKE "%SupplyFan%")
  OPTIONAL { ?uri a ?class }
}

SELECT ?uri ?id WHERE {
  ?uri ref:hasExternalReference ?id .
  ?uri brick:hasSubEntity ?e .
  MINUS { ?uri a brick:Sensor }
}

